    f.circle(100, 110, 30, "#ffca28"); f.line(125, 130, 230, 290, "#f9a825", 2.5, arrow=True); f.line(250, 290, 330, 120, "#e64a19", 2.5, arrow=True); f.rect(300, 90, 70, 30, "#607d8b", rx=4)
    f.rect(60, 300, 380, 24, "#a5d6a7"); f.text(250, 360, "អកម្ម៖ Landsat Sentinel-2 · ត្រូវការពន្លឺព្រះអាទិត្យ", 15, IND, "middle", "bold")
    f.rect(700, 90, 70, 30, "#607d8b", rx=4); f.line(720, 125, 640, 290, "#1e88e5", 2.5, arrow=True); f.line(660, 290, 750, 125, "#8e24aa", 2.5, "6 4", arrow=True)
