    # 6 what RS can/cannot
    f = Fig(1000, 440).title("អ្វីដែលការយកព័ត៌មានពីចម្ងាយអាច និងមិនអាច")
    f.rect(40, 90, 440, 310, "#e8f5e9", "#81c784", 2, 12); f.text(260, 125, "✓ អាច", 22, "#2e7d32", "middle", "bold")
    for i, t in enumerate(["ផែនទីគម្របដី និងការផ្លាស់ប្ដូរ", "វាស់ផ្ទៃទឹកជំនន់", "តាមដានសុខភាពដំណាំ (NDVI)", "វាស់សីតុណ្ហភាពផ្ទៃ", "គ្របតំបន់ធំ ម្ដងទៀតៗ"]): f.text(70, 170 + i * 44, "• " + t, 17)
    f.rect(520, 90, 440, 310, "#ffebee", "#e57373", 2, 12); f.text(740, 125, "✗ មិនអាចផ្ទាល់", 22, "#c62828", "middle", "bold")
