def L02():
    # 1 spectrum with sensor bands
    f = Fig(1000, 440).title("វិសាលគម និងក្រុមរលក Landsat 8 · Sentinel-2", "រលកចម្ងាយ (µm) · អ័ក្សលោការីត")
    x0, w = 60, 880; X = lambda um: x0 + (math.log10(um) - math.log10(.35)) / (math.log10(15) - math.log10(.35)) * w
    for a, b, c, t in [(.38, .45, "#6a1b9a", ""), (.45, .495, "#1e88e5", ""), (.495, .57, "#43a047", ""), (.57, .59, "#fdd835", ""), (.59, .62, "#fb8c00", ""), (.62, .75, "#e53935", ""), (.75, 1.3, "#8d6e63", "NIR"), (1.3, 3, "#a1887f", "SWIR"), (3, 8, "#bcaaa4", "MIR"), (8, 15, "#d7ccc8", "TIR")]:
        f.rect(X(a), 100, X(b) - X(a), 40, c); f.text((X(a) + X(b)) / 2, 125, t, 13, "#fff" if t in ("NIR", "SWIR") else INK, "middle", "bold")
    f.text(X(.55), 92, "ពន្លឺមើលឃើញ", 13, INK, "middle")
    L8 = [("1", .433, .453), ("2", .45, .515), ("3", .525, .6), ("4", .63, .68), ("5", .845, .885), ("6", 1.56, 1.66), ("7", 2.1, 2.3), ("10", 10.6, 11.19), ("11", 11.5, 12.51)]
    S2 = [("2", .458, .523), ("3", .543, .578), ("4", .65, .68), ("5", .698, .713), ("6", .733, .748), ("7", .773, .793), ("8", .785, .9), ("11", 1.565, 1.655), ("12", 2.1, 2.28)]
    for row, (nm, bands, c) in enumerate([("Landsat 8", L8, IND), ("Sentinel-2", S2, "#e64a19")]):
        y = 180 + row * 70; f.text(x0, y - 8, nm, 15, c, weight="bold")
        for t, a, b in bands: f.rect(X(a), y, max(3, X(b) - X(a)), 30, c, op=None) if False else f.add(f'<rect x="{X(a):.1f}" y="{y}" width="{max(3,X(b)-X(a)):.1f}" height="30" fill="{c}" opacity=".85"/>'); f.text((X(a) + X(b)) / 2, y + 48, "B" + t, 11, c, "middle")
    for um in (.4, .5, .7, 1, 2, 3, 5, 10): f.text(X(um), 350, kh(um), 13, "#546e7a", "middle")
    f.text(500, 390, "Sentinel-2 មានក្រុមរលក red-edge (B5–B7) · Landsat មានក្រុមរលកកម្ដៅ (B10–B11)", 15, INK, "middle")
    entry(2, f.save("r02-spectrum-bands"), "ក្រុមរលកស្ថិតនៅកន្លែងណាលើវិសាលគម",
          ["ក្រុមរលកនីមួយៗជាចន្លោះតូចមួយនៃវិសាលគម។", "ក្រុមរលកត្រូវបានរចនាឲ្យនៅក្នុងបង្អួចបរិយាកាស។", "ឈ្មោះលេខក្រុមរលកខុសគ្នារវាងឧបករណ៍៖ NIR = B5 (Landsat) · B8 (Sentinel-2)។"], .3)
    # 2 Planck curves
    f = Fig(1000, 460).title("ច្បាប់ Planck៖ ព្រះអាទិត្យ ធៀបនឹងផែនដី", "រូបរាងខ្សែកោង (ធ្វើឲ្យ normalize) · កំពូលតាមច្បាប់ Wien")
    h, c, k = 6.626e-34, 3e8, 1.381e-23
    def B(lam_um, T): l = lam_um * 1e-6; return 2 * h * c * c / l ** 5 / (math.exp(h * c / (l * k * T)) - 1)
    xs = [10 ** (math.log10(.2) + i * (math.log10(50) - math.log10(.2)) / 300) for i in range(301)]
    s1 = [B(x, 5800) for x in xs]; s2 = [B(x, 300) for x in xs]; m1, m2 = max(s1), max(s2)
    chart(f, 100, 90, 700, 280, [(xs, [v / m1 for v in s1], "#f9a825", "ព្រះអាទិត្យ ៥ ៨០០ K", 3), (xs, [v / m2 for v in s2], "#e53935", "ផែនដី ៣០០ K", 3)], (.2, 50), (0, 1.05),
          "រលកចម្ងាយ (µm)", "អាំងតង់ស៊ីតេ (ធៀប)", xt=[.2, .5, 1, 2, 5, 10, 20, 50], yt=[0, .5, 1], log=True, bands=[(.4, .7, "#fff176", "មើលឃើញ"), (8, 14, "#ffcdd2", "TIR")])
    f.text(820, 300, "Wien៖ λmax = 2898 / T", 15, INK); f.text(820, 330, "ព្រះអាទិត្យ → ០,៥ µm", 14, "#f9a825", weight="bold"); f.text(820, 355, "ផែនដី → ៩,៧ µm", 14, "#e53935", weight="bold")
    entry(2, f.save("r02-planck"), "វត្ថុក្ដៅបញ្ចេញរលកខ្លី",
          ["ព្រះអាទិត្យបញ្ចេញខ្លាំងបំផុតក្នុងពន្លឺមើលឃើញ (~០,៥ µm)។", "ផែនដីបញ្ចេញកម្ដៅក្នុង TIR (~១០ µm)៖ ដូច្នេះ Landsat B10 វាស់សីតុណ្ហភាព។", "ក្រុមរលកចាំងផ្លាត (VNIR–SWIR) និងក្រុមរលកបញ្ចេញ (TIR) ដាច់ពីគ្នាប្រហែល ៣–៥ µm។"], .45)
    # 3 atmospheric windows
    f = Fig(1000, 460).title("បង្អួចបរិយាកាស", "ការឆ្លងកាត់ប្រហាក់ប្រហែល (សម្រាប់បង្រៀន)")
    xs = [10 ** (math.log10(.3) + i * (math.log10(15) - math.log10(.3)) / 400) for i in range(401)]
    def T(x):
        t = 1 - math.exp(-((x - .3) / .08) ** 2) if x < .4 else .85
        for c0, wdt, d in [(.94, .03, .5), (1.14, .04, .6), (1.4, .08, .95), (1.9, .1, .98), (2.7, .15, .99), (4.3, .15, .9), (6.3, 1.2, .99), (9.6, .3, .5)]: t -= d * math.exp(-((x - c0) / wdt) ** 2)
        if 14 < x: t *= .2
        return max(0, min(1, t))
    chart(f, 100, 90, 800, 260, [(xs, [T(x) for x in xs], "#1565c0", "", 2.5)], (.3, 15), (0, 1), "រលកចម្ងាយ (µm)", "ការឆ្លងកាត់", xt=[.3, .5, 1, 2, 3, 5, 10, 15], yt=[0, .5, 1], log=True, legend=False,
          bands=[(.43, .45, "#6a1b9a", "B1"), (.45, .68, "#43a047", "B2–4"), (.845, .885, "#8d6e63", "B5"), (1.56, 1.66, "#a1887f", "B6"), (2.1, 2.3, "#a1887f", "B7"), (10.6, 12.5, "#e53935", "B10–11")])
    f.text(500, 440, "ការស្រូបដោយ H₂O · CO₂ · O₃ បិទចន្លោះខ្លះ៖ ក្រុមរលកត្រូវតែនៅក្នុង «បង្អួច»", 15, INK, "middle")
    entry(2, f.save("r02-windows"), "ហេតុអ្វីក្រុមរលកនៅកន្លែងទាំងនោះ",
          ["ចំហាយទឹកស្រូបខ្លាំងនៅ ១,៤ និង ១,៩ µm → គ្មានក្រុមរលកនៅទីនោះ។", "Landsat B9 (១,៣៧ µm) ផ្ទុយពីនេះ ត្រូវបានដាក់ក្នុងកន្លែងស្រូបខ្លាំង ដើម្បីរកពពក cirrus។", "បង្អួច ៨–១៤ µm អនុញ្ញាតឲ្យវាស់សីតុណ្ហភាពផ្ទៃ។"], .6)
    # 4 real bands B2..B7 showing haze
    f = Fig(1000, 470).title("ក្រុមរលកទាំងប្រាំមួយនៃរូបភាពតែមួយ", "ស ខ្មៅ · stretch ដូចគ្នា (០ – ០,៣៥)")
    for i, (b, t) in enumerate([(2, "B2 ខៀវ"), (3, "B3 បៃតង"), (4, "B4 ក្រហម"), (5, "B5 NIR"), (6, "B6 SWIR1"), (7, "B7 SWIR2")]):
        a = R.crop(R.toa(b)); im = Image.fromarray((np.clip(a / .35, 0, 1) * 255).astype(np.uint8))
        x, y = 30 + (i % 3) * 320, 85 + (i // 3) * 190; f.img(im, x, y, 300, 160); f.text(x + 150, y + 180, t, 14, IND, "middle", "bold")
    f.source(SRC_L8)
    entry(2, f.save("r02-bands-grid"), "ក្រុមរលកនីមួយៗប្រាប់រឿងខុសគ្នា",
          ["B2 (ខៀវ) មើលទៅ «ស្រអាប់» ព្រោះការខ្ចាត់ Rayleigh ខ្លាំងនៅរលកខ្លី។", "B5 (NIR) ទឹកខ្មៅ រុក្ខជាតិភ្លឺខ្លាំង៖ ល្អសម្រាប់បំបែកទឹក។", "B6–B7 (SWIR) បង្ហាញសំណើមដី និងសំណង់ច្បាស់។"], .75)
    # 5 Rayleigh curve
    f = Fig(1000, 420).title("ការខ្ចាត់ Rayleigh ∝ 1/λ⁴")
    xs = [.4 + i * .006 for i in range(101)]; ys = [(.45 / x) ** 4 for x in xs]
    chart(f, 100, 90, 520, 250, [(xs, ys, "#1e88e5", "", 3)], (.4, 1.0), (0, 1.6), "រលកចម្ងាយ (µm)", "ការខ្ចាត់ (ធៀបនឹង ០,៤៥ µm)", xt=[.4, .5, .6, .7, .8, .9, 1.0], yt=[0, .5, 1, 1.5], legend=False)
    vals = [float(np.percentile(R.crop(R.toa(b)), 2)) for b in (2, 3, 4, 5)]
    bars(f, 660, 110, 320, 200, ["B2", "B3", "B4", "B5"], vals, ["#1e88e5", "#43a047", "#e53935", "#8d6e63"], fmt=lambda v: kh(round(v, 3)), lw=50)
    f.text(820, 350, "ភាគរយ ២% ងងឹតបំផុត (ផ្លូវពន្លឺ)", 13, "#607d8b", "middle")
    entry(2, f.save("r02-rayleigh"), "ភាពស្រអាប់ដោយបរិយាកាស",
          ["ពន្លឺខៀវខ្ចាត់ខ្លាំងជាង NIR ប្រហែល ១០ ដង ដែលធ្វើឲ្យមេឃពណ៌ខៀវ។", "ក្នុងរូបភាពពិត តម្លៃ «ងងឹតបំផុត» នៃ B2 ខ្ពស់ជាង B5 ច្រើន៖ នេះជាផ្លូវពន្លឺបរិយាកាស។", "វិធី DOS (មេរៀនទី៧) ដកតម្លៃនេះចេញ។"], .7)

def L03():
    cls = R.CLS; bands = [2, 3, 4, 5, 6, 7]; wl = [.48, .56, .655, .865, 1.61, 2.2]
    means = [[float(R.SCB[b][cls == c].mean()) for b in bands] for c in range(5)]
    # 1 real signatures
    f = Fig(1000, 460).title("សញ្ញាណស្ពិចត្រាល់ពីរូបភាពពិត", "មធ្យមនៃក្រឡាតាមថ្នាក់ · Landsat 8 TOA")
    chart(f, 100, 90, 620, 290, [(wl, means[c], R.CLASS_COL[c] if c != 4 else "#8d6e63", R.CLASS_KH[c], 3) for c in range(5)], (.4, 2.3), (0, .45), "រលកចម្ងាយ (µm)", "ការចាំងផ្លាត", xt=[.5, 1.0, 1.5, 2.0], yt=[0, .1, .2, .3, .4], lx=760, ly=130)
    entry(3, f.save("r03-real-signatures"), "សញ្ញាណស្ពិចត្រាល់ពិតនៃភ្នំពេញ",
          ["ដើមឈើ៖ ទាបក្នុងក្រហម ខ្ពស់ខ្លាំងក្នុង NIR (ជញ្ជាំងក្រហម)។", "ទឹក៖ ទាបគ្រប់ក្រុមរលក ជាពិសេស NIR និង SWIR។", "សំណង់ និងដីទទេ៖ ភ្លឺ និងរាបស្មើ ពិបាកបំបែកពីគ្នា។"], .45)
    # 2 red-NIR scatter
    f = Fig(1000, 470).title("លំហលក្ខណៈ ក្រហម × NIR", "ចំណុចនីមួយៗជាក្រឡាមួយ (គំរូ ១ ៥០០)")
    rng = np.random.default_rng(0); idx = rng.choice(300 * 300, 1500, replace=False)
    X0, Y0, W, H = 120, 80, 360, 340; f.rect(X0, Y0, W, H, "#fff", "#cfd8dc")
    r = R.SCB[4].ravel()[idx]; n = R.SCB[5].ravel()[idx]; c = cls.ravel()[idx]
    for a, b, k in zip(r, n, c): f.circle(X0 + a / .3 * W, Y0 + H - b / .45 * H, 2.2, R.CLASS_COL[k] if k != 4 else "#8d6e63", op=.7)
    f.line(X0, Y0 + H, X0 + W, Y0 + H - W / .45 * .3 * H / W, "#9e9e9e", 1, "5 4"); f.text(X0 + W / 2, Y0 + H + 30, "ក្រហម (B4)", 14, INK, "middle"); f.text(X0 - 40, Y0 + H / 2, "NIR (B5)", 14, INK, "middle")
    for i in range(5): f.circle(560, 140 + i * 36, 7, R.CLASS_COL[i] if i != 4 else "#8d6e63"); f.text(576, 146 + i * 36, R.CLASS_KH[i], 16)
    f.text(560, 350, "ខ្សែដាច់ៗ = បន្ទាត់ដីទទេ (soil line)", 14, "#607d8b"); f.text(560, 378, "រុក្ខជាតិនៅខាងលើ · ទឹកនៅជ្រុងក្រោម", 14, "#607d8b")
    entry(3, f.save("r03-red-nir"), "រុក្ខជាតិ ទឹក និងដី ក្នុងលំហក្រហម–NIR",
          ["ថ្នាក់ផ្សេងៗកាន់កាប់តំបន់ខុសគ្នាក្នុងលំហលក្ខណៈ។", "ការត្រួតគ្នារវាងសំណង់ និងដីទទេ ពន្យល់ពីកំហុសចាត់ថ្នាក់ក្រោយ។", "NDVI (មេរៀនទី១០) វាស់ចម្ងាយពីបន្ទាត់ដីទទេ។"], .8)
    # 3 idealized library curves
    f = Fig(1000, 440).title("សញ្ញាណគំរូ៖ រុក្ខជាតិ ដី ទឹក", "ខ្សែកោងប្រហាក់ប្រហែល (សម្រាប់បង្រៀន)")
    xs = [.4 + i * .01 for i in range(211)]
    veg = [.04 + .06 * math.exp(-((x - .55) / .03) ** 2) + (.45 / (1 + math.exp(-(x - .72) / .012))) * (1 if x < 1.3 else .7) - .25 * math.exp(-((x - 1.45) / .06) ** 2) - .3 * math.exp(-((x - 1.95) / .08) ** 2) for x in xs]
    soil = [.1 + .2 * (x - .4) / 1.8 + .05 * math.sin(x * 3) - .04 * math.exp(-((x - 1.9) / .05) ** 2) for x in xs]
    wat = [max(.005, .08 * math.exp(-((x - .45) / .15) ** 2)) for x in xs]
    chart(f, 100, 90, 640, 270, [(xs, [max(0, v) for v in veg], "#2e7d32", "រុក្ខជាតិ", 3), (xs, soil, "#8d6e63", "ដី", 3), (xs, wat, "#1e88e5", "ទឹក", 3)], (.4, 2.5), (0, .6), "រលកចម្ងាយ (µm)", "ការចាំងផ្លាត", xt=[.5, 1.0, 1.5, 2.0, 2.5], yt=[0, .2, .4, .6], lx=780, ly=140,
          bands=[(.62, .69, "#e53935", "ក្រហម"), (.7, .75, "#ff8a65", "red-edge"), (1.4, 1.5, "#90caf9", "H₂O"), (1.85, 2.0, "#90caf9", "H₂O")])
    entry(3, f.save("r03-library"), "លក្ខណៈសំខាន់ៗនៃសញ្ញាណ",
          ["រុក្ខជាតិ៖ កំពូលបៃតងតូច ស្រូបក្រហម (chlorophyll) និង red-edge ចោត។", "ទឹកក្នុងស្លឹក បង្កើតរណ្ដៅស្រូបនៅ ១,៤ និង ១,៩ µm។", "ដីកើនបន្តិចម្ដងៗ ហើយងងឹតជាងពេលសើម។"], .3)
    # 4 specular vs diffuse
    f = Fig(1000, 380).title("ការចាំងផ្លាតបែបកញ្ចក់ និងបែបរាយ")
    for i, (t, sub) in enumerate([("បែបកញ្ចក់ (specular)", "ទឹករលោង · ដំបូលដែក"), ("បែបរាយ (diffuse)", "ដី ព្រៃ ស្មៅ")]):
        x0 = 80 + i * 470; f.rect(x0, 260, 360, 16, "#90a4ae"); f.line(x0 + 40, 100, x0 + 180, 255, "#f9a825", 3, arrow=True)
        if i == 0: f.line(x0 + 185, 255, x0 + 320, 100, "#e64a19", 3, arrow=True)
        else:
            for a in range(20, 170, 25): f.line(x0 + 185, 255, x0 + 185 + 110 * math.cos(math.radians(a)), 255 - 110 * math.sin(math.radians(a)), "#e64a19", 2, arrow=True)
        f.text(x0 + 180, 310, t, 17, IND, "middle", "bold"); f.text(x0 + 180, 338, sub, 14, "#607d8b", "middle")
    entry(3, f.save("r03-specular"), "ផ្ទៃរលោង និងផ្ទៃគ្រើម",
          ["ផ្ទៃរលោងចាំងពន្លឺទៅទិសតែមួយ៖ ឃើញភ្លឺខ្លាំង (sun glint) ឬងងឹតខ្លាំង។", "ផ្ទៃគ្រើមចាំងរាយគ្រប់ទិស៖ ពន្លឺមិនអាស្រ័យលើមុំមើលខ្លាំង។", "ទឹកមានខ្យល់បក់ ឬទឹកល្អក់ អាចភ្លឺជាងទឹករលោង។"], .2)
    # 5 separability per band
    f = Fig(1000, 420).title("ក្រុមរលកណាបំបែកដើមឈើ និងដំណាំបានល្អបំផុត?", "|មធ្យម១ − មធ្យម២| ÷ (SD១ + SD២)")
    sep = []
    for b in bands:
        a = R.SCB[b][cls == 1]; c2 = R.SCB[b][cls == 2]; sep.append(abs(a.mean() - c2.mean()) / (a.std() + c2.std()))
    bars(f, 80, 100, 820, 260, [f"B{b}" for b in bands], sep, ["#1e88e5", "#43a047", "#e53935", "#8d6e63", "#a1887f", "#6d4c41"], fmt=lambda v: kh(round(float(v), 2)), lw=80)
    entry(3, f.save("r03-separability"), "ភាពបែងចែករវាងថ្នាក់",
          ["តម្លៃខ្ពស់ = ថ្នាក់ពីរដាច់ពីគ្នាល្អក្នុងក្រុមរលកនោះ។", "ក្រុមរលកដែលល្អបំផុតខុសគ្នាតាមគូថ្នាក់ដែលចង់បំបែក។", "ការរួមក្រុមរលកច្រើន (ឬសន្ទស្សន៍) ជាទូទៅបំបែកបានល្អជាងក្រុមរលកតែមួយ។"], .9)
    # 6 same class, different conditions: SHV NDVI 2015 vs 2021 hist
    s15, s21 = R.shv(2015), R.shv(2021); n15, n21 = R.nd(s15[4], s15[3]).ravel(), R.nd(s21[4], s21[3]).ravel()
    f = Fig(1000, 420).title("ការចែកចាយ NDVI៖ ក្រុងព្រះសីហនុ ២០១៥ និង ២០២១", "Sentinel-2")
    bins = np.linspace(-.3, .9, 25); h15 = np.histogram(n15, bins)[0]; h21 = np.histogram(n21, bins)[0]; mx = max(h15.max(), h21.max())
    ctr = (bins[:-1] + bins[1:]) / 2
    chart(f, 100, 90, 640, 250, [(list(ctr), list(h15 / mx), "#2e7d32", "២០១៥", 3), (list(ctr), list(h21 / mx), "#e64a19", "២០២១", 3)], (-.3, .9), (0, 1.05), "NDVI", "ភាគចំណែក", xt=[-.2, 0, .2, .4, .6, .8], yt=[0, .5, 1], lx=780, ly=150)
    entry(3, f.save("r03-shv-ndvi-hist"), "សញ្ញាណផ្លាស់ប្ដូរតាមពេលវេលា",
          ["ឆ្នាំ ២០២១ មានក្រឡា NDVI ទាប (ដីឈូសឆាយ សំណង់) ច្រើនជាងឆ្នាំ ២០១៥។", "ព្រៃដដែលអាចមាន NDVI ខុសគ្នាតាមរដូវ និងលក្ខខណ្ឌបរិយាកាស។", "ដូច្នេះប្រៀបធៀបរូបភាពពីរដូវដូចគ្នា (មេរៀនទី១៤)។"], .7)

def L04():
    # 1 DN histogram B4 raw
    d = R.dn(4).ravel()
    f = Fig(1000, 420).title("តម្លៃលេខ (DN) នៃ B4 ក្នុងឯកសារដើម", "Landsat 8 Level-1 · ១៦ ប៊ីត")
    bins = np.linspace(d.min(), np.percentile(d, 99.8), 50); h = np.histogram(d, bins)[0]
    for i, v in enumerate(h): f.rect(100 + i * 16, 340 - v / h.max() * 230, 14, v / h.max() * 230, "#e53935")
    f.text(100, 370, kh(int(bins[0])), 13, "#546e7a"); f.text(900, 370, kh(int(bins[-1])), 13, "#546e7a", "end"); f.text(500, 395, "DN (០ – ៦៥ ៥៣៥ អាចមាន)", 14, INK, "middle")
    f.text(620, 140, "DN មិនមែនការចាំងផ្លាតទេ", 17, INK, weight="bold"); f.text(620, 170, "ρ = DN × 2·10⁻⁵ − 0,1", 17, "#e64a19"); f.text(620, 200, "(ពីឯកសារ MTL)", 14, "#607d8b")
    entry(4, f.save("r04-dn-hist"), "ពីពន្លឺទៅលេខ",
          ["ឧបករណ៍ចាប់សញ្ញាបម្លែងពន្លឺជាចរន្តអគ្គិសនី រួចជាលេខគត់ (DN)។", "DN ភាគច្រើនប្រមូលផ្ដុំក្នុងចន្លោះតូច៖ ត្រូវ stretch ដើម្បីមើល។", "មេគុណ MULT និង ADD បម្លែង DN ទៅការចាំងផ្លាត TOA (មេរៀនទី៧)។"], .15)
    # 2 IFOV/GSD diagram
    f = Fig(1000, 440).title("IFOV និង GSD", "GSD = កម្ពស់ × IFOV")
    f.rect(460, 80, 80, 36, "#607d8b", rx=6); f.text(500, 104, "ឧបករណ៍", 13, "#fff", "middle")
    f.path("M 500 116 L 440 360 L 560 360 Z", "#fff3e0", "#e64a19", 1.5); f.rect(440, 360, 120, 16, "#a5d6a7", "#2e7d32")
    f.text(500, 400, "GSD ≈ ៣០ ម", 16, IND, "middle", "bold"); f.text(520, 240, "IFOV ≈ ៤២ µrad", 14, "#e64a19")
    f.text(640, 150, "កម្ពស់ Landsat ៧០៥ គម", 16); f.text(640, 185, "៧០៥ ០០០ ម × ៤២·១០⁻⁶ ≈ ៣០ ម", 16, INK, weight="bold"); f.text(640, 240, "ឧបករណ៍ទាបជាង → GSD តូចជាង", 15, "#607d8b"); f.text(640, 268, "ដ្រូន ១០០ ម → សង់ទីម៉ែត្រ", 15, "#607d8b")
    entry(4, f.save("r04-ifov"), "ទំហំក្រឡាអាស្រ័យលើកម្ពស់ និង IFOV",
          ["IFOV ជាមុំដែលធាតុចាប់សញ្ញាមួយ «មើលឃើញ»។", "GSD = កម្ពស់ × IFOV (រ៉ាដ្យង់)។", "នៅគែមរូបភាព (មុំទ្រេត) ក្រឡាលើដីធំជាងនៅកណ្ដាល។"], .3)
    # 3 pushbroom vs whiskbroom
    f = Fig(1000, 420).title("របៀបស្កេនពីរ")
    for i, (t, sub) in enumerate([("Whiskbroom (ច្រាសស្កេន)", "Landsat 5–7 · កញ្ចក់វិលស្កេនពីម្ខាងទៅម្ខាង"), ("Pushbroom (អំបោស)", "Landsat 8–9 · Sentinel-2 · ជួរធាតុចាប់សញ្ញារាប់ពាន់")]):
        x0 = 60 + i * 470
        for r in range(6):
            for c in range(10): f.rect(x0 + c * 34, 110 + r * 30, 34, 30, "#e0f2f1" if r < 3 else "#fafafa", "#b0bec5", .6)
        if i == 0: f.line(x0, 185, x0 + 330, 185, "#e64a19", 3, arrow=True); f.circle(x0 + 20, 185, 8, "#e64a19")
        else: f.rect(x0, 180, 340, 10, "#e64a19")
        f.line(x0 + 360, 110, x0 + 360, 290, "#607d8b", 2, arrow=True); f.text(x0 + 372, 200, "ទិសហោះ", 12, "#607d8b")
        f.text(x0 + 170, 330, t, 16, IND, "middle", "bold"); f.text(x0 + 170, 358, sub, 13, "#607d8b", "middle")
    entry(4, f.save("r04-scanning"), "Whiskbroom ធៀបនឹង Pushbroom",
          ["Whiskbroom៖ ធាតុតិច ប៉ុន្តែមានផ្នែកវិល និងពេលវាស់ខ្លីក្នុងមួយក្រឡា។", "Pushbroom៖ វាស់ក្រឡាមួយបានយូរជាង → សញ្ញាខ្លាំង សំឡេងរំខានតិច។", "Pushbroom អាចមានឆ្នូតបញ្ឈរ ពេលធាតុចាប់សញ្ញាមួយខុសពីគេ។"], .5)
    # 4 revisit vs swath scatter
    f = Fig(1000, 440).title("ទទឹងគ្របដណ្ដប់ ធៀបនឹងរយៈពេលមកម្ដងទៀត")
    S = [("Landsat 8+9", 185, 8, 30), ("Sentinel-2A+B", 290, 5, 10), ("MODIS", 2330, 1, 250), ("Sentinel-1", 250, 6, 10), ("PlanetScope", 25, 1, 3), ("WorldView-3", 13, 4, .31)]
    X0, Y0, W, H = 120, 80, 640, 280; f.rect(X0, Y0, W, H, "#fff", "#cfd8dc")
    xl = lambda v: X0 + (math.log10(v) - 1) / (math.log10(3000) - 1) * W; yl = lambda v: Y0 + H - (v / 18) * H
    for nm, sw, rv, res in S:
        x, y = xl(sw), yl(rv); f.circle(x, y, 6 + 10 * (1 - min(1, math.log10(res + 1) / 2.5)), "#e64a19", "#fff", 1, .85); f.text(x + 12, y - 8, f"{nm} ({kh(res)} ម)", 13)
    for v in (10, 100, 1000): f.text(xl(v), Y0 + H + 20, kh(v), 12, "#546e7a", "middle")
    for v in (0, 5, 10, 15): f.text(X0 - 8, yl(v) + 4, kh(v), 12, "#546e7a", "end")
    f.text(X0 + W / 2, Y0 + H + 45, "ទទឹងគ្របដណ្ដប់ (គម · log)", 14, INK, "middle"); f.text(X0 - 50, Y0 + H / 2, "ថ្ងៃ", 14, INK, "middle")
    entry(4, f.save("r04-swath-revisit"), "ការសម្របសម្រួលនៃការរចនាផ្កាយរណប",
          ["ទទឹងធំ (MODIS) = មកម្ដងទៀតរាល់ថ្ងៃ ប៉ុន្តែក្រឡាធំ។", "ក្រឡាតូច (WorldView) = ទទឹងតូច និងថ្លៃ។", "ផ្កាយរណបច្រើនគ្រឿងជាក្រុម (Sentinel-2A+B, Planet) កាត់បន្ថយរយៈពេលមកម្ដងទៀត។"], .7)
    # 5 processing levels
    f = Fig(1000, 380).title("កម្រិតដំណើរការទិន្នន័យ")
    for i, (t, sub, c) in enumerate([("Level-0", "សញ្ញាឆៅ", "#9e9e9e"), ("Level-1", "DN · ធរណីមាត្រ (L1TP)", "#8d6e63"), ("Level-1C", "TOA (Sentinel-2)", "#6d4c41"), ("Level-2", "ការចាំងផ្លាតផ្ទៃ", "#e64a19"), ("Level-3", "ផលិតផល (NDVI ប្រចាំខែ)", "#5d4037")]):
        x = 30 + i * 192; f.rect(x, 140, 175, 100, c, rx=12); f.text(x + 87, 182, t, 18, "#fff", "middle", "bold"); f.text(x + 87, 212, sub, 12, "#fff", "middle")
        if i < 4: f.line(x + 176, 190, x + 190, 190, "#607d8b", 2, arrow=True)
    f.text(500, 300, "ឈ្មោះឯកសារ៖ LC08_L1TP_126052_20190211_… = Landsat 8 · Level-1 · Path 126 Row 52 · ២០១៩-០២-១១", 14, INK, "middle")
    entry(4, f.save("r04-levels"), "ជ្រើសកម្រិតដំណើរការ",
          ["Level-1 ត្រូវកែតម្រូវរ៉ាដ្យូម៉ែត្រដោយខ្លួនឯង (លំហាត់ទី៧)។", "Level-2 (surface reflectance) រួចរាល់សម្រាប់វិភាគ និងប្រៀបធៀបពេលវេលា។", "អានឈ្មោះឯកសារដើម្បីដឹង ឧបករណ៍ កម្រិត ទីតាំង និងកាលបរិច្ឆេទ។"], .9)

def L05():
    B = {b: R.crop(R.toa(b)) for b in range(2, 8)}
    # 1 radiometric quantization
    f = Fig(1000, 440).title("គុណភាពបង្ហាញរ៉ាដ្យូម៉ែត្រ៖ ១ · ២ · ៤ · ៨ ប៊ីត")
    a = R.stretch(B[5]).astype(float) / 255
    for i, bits in enumerate([1, 2, 4, 8]):
        lv = 2 ** bits; q = (np.floor(a * (lv - 1) + .5) / (lv - 1) * 255).astype(np.uint8)
        f.img(Image.fromarray(q), 20 + i * 245, 90, 225, 200); f.text(132 + i * 245, 320, f"{kh(bits)} ប៊ីត = {khn(lv)} កម្រិត", 15, IND, "middle", "bold")
    f.text(500, 380, "Landsat 8 = ១២ ប៊ីត (៤ ០៩៦ កម្រិត) · Landsat 5 = ៨ ប៊ីត (២៥៦) · ភ្នែកបែងចែកបាន ~៥០–១០០ កម្រិតប្រផេះ", 14, INK, "middle")
    entry(5, f.save("r05-bits"), "ចំនួនកម្រិតពន្លឺ",
          ["ប៊ីតច្រើន = បែងចែកភាពខុសគ្នាតូចៗបាន (ឧ. ទឹកល្អក់ធៀបនឹងទឹកថ្លា)។", "ភាពខុសគ្នារវាង ៨ និង ១២ ប៊ីត មើលមិនឃើញដោយភ្នែក ប៉ុន្តែសំខាន់ក្នុងការគណនា។", "ប៊ីតច្រើន ធ្វើឲ្យឯកសារធំ។"], .5)
    # 2 spectral resolution: band widths
    f = Fig(1000, 420).title("គុណភាពបង្ហាញស្ពិចត្រាល់", "ចំនួន និងទទឹងក្រុមរលក ០,៤ – ២,៥ µm")
    x0, w = 120, 800; X = lambda um: x0 + (um - .4) / 2.1 * w
    rows = [("RGB កាមេរ៉ា", [(.4, .5), (.5, .6), (.6, .7)]), ("Landsat 8", [(.433, .453), (.45, .515), (.525, .6), (.63, .68), (.845, .885), (1.56, 1.66), (2.1, 2.3)]),
            ("Sentinel-2", [(.433, .453), (.458, .523), (.543, .578), (.65, .68), (.698, .713), (.733, .748), (.773, .793), (.785, .9), (.855, .875), (1.565, 1.655), (2.1, 2.28)]), ("Hyperspectral", [(.4 + i * .0105, .4 + i * .0105 + .009) for i in range(200)])]
    for r, (nm, bs) in enumerate(rows):
        y = 100 + r * 65; f.text(x0 - 10, y + 22, nm, 14, INK, "end", "bold")
        for a_, b_ in bs: f.rect(X(a_), y, max(1.2, X(b_) - X(a_)), 34, ["#8d6e63", IND, "#e64a19", "#6a1b9a"][r], extra='opacity=".85"')
    for um in (.5, 1.0, 1.5, 2.0, 2.5): f.text(X(um), 380, kh(um) + " µm", 12, "#546e7a", "middle")
    entry(5, f.save("r05-spectral"), "ក្រុមរលកច្រើន និងស្ដើង",
          ["កាមេរ៉ាធម្មតា៖ ៣ ក្រុមរលកធំ មិនមាន NIR។", "Sentinel-2៖ ១៣ ក្រុមរលក រួមទាំង red-edge ដែលរសើបនឹងសុខភាពដំណាំ។", "Hyperspectral៖ រាប់រយក្រុមរលក ដែលអាចបែងចែកប្រភេទរុក្ខជាតិ ឬរ៉ែ។"], .3)
    # 3 temporal: revisit calendar Feb 2019
    f = Fig(1000, 420).title("គុណភាពបង្ហាញពេលវេលា៖ រូបភាពក្នុងមួយខែ", "ឧទាហរណ៍ភ្នំពេញ · ខែកុម្ភៈ")
    for d in range(28):
        x = 120 + (d % 7) * 110; y = 90 + (d // 7) * 70; f.rect(x, y, 100, 60, "#fafafa", "#e0e0e0", 1, 6); f.text(x + 8, y + 18, kh(d + 1), 12, "#90a4ae")
        if d % 5 == 1: f.circle(x + 35, y + 40, 9, "#e64a19")
        if d % 16 == 10: f.rect(x + 55, y + 31, 18, 18, IND)
        if d % 6 == 3: f.path(f"M {x+80} {y+45} l 8 -14 l 8 14 z", "#8e24aa")
    f.circle(140, 390, 8, "#e64a19"); f.text(155, 395, "Sentinel-2 (៥ ថ្ងៃ)", 14); f.rect(360, 382, 16, 16, IND); f.text(385, 395, "Landsat 8 (១៦ ថ្ងៃ)", 14); f.path("M 590 398 l 8 -14 l 8 14 z", "#8e24aa"); f.text(615, 395, "Sentinel-1 (៦ ថ្ងៃ · SAR)", 14)
    entry(5, f.save("r05-temporal"), "រូបភាពញឹកញាប់ប៉ុណ្ណា",
          ["Sentinel-2 ផ្ដល់ ~៦ រូបភាពក្នុងមួយខែ ប៉ុន្តែនៅរដូវវស្សា ភាគច្រើនមានពពក។", "Landsat ផ្ដល់ត្រឹម ២ រូបភាព (ឬ ៤ ពេលរួម Landsat 9)។", "SAR (Sentinel-1) ឆ្លងពពក៖ សំខាន់សម្រាប់តាមដានទឹកជំនន់។"], .7)
    # 4 trade-off triangle scatter res vs swath
    f = Fig(1000, 440).title("ត្រីកោណនៃការសម្របសម្រួល", "គុណភាពបង្ហាញលំហ ធៀបនឹងទទឹងគ្របដណ្ដប់")
    S = [("WorldView-3", .31, 13), ("Pleiades", .5, 20), ("PlanetScope", 3, 25), ("Sentinel-2", 10, 290), ("Landsat 8", 30, 185), ("Sentinel-3", 300, 1270), ("MODIS", 250, 2330), ("VIIRS", 375, 3000)]
    X0, Y0, W, H = 120, 80, 700, 280; f.rect(X0, Y0, W, H, "#fff", "#cfd8dc")
    xl = lambda v: X0 + (math.log10(v) + .6) / (math.log10(500) + .6) * W; yl = lambda v: Y0 + H - (math.log10(v) - 1) / (math.log10(4000) - 1) * H
    for nm, res, sw in S: x, y = xl(res), yl(sw); f.circle(x, y, 7, "#e64a19", "#fff"); f.text(x + 10, y - 8, nm, 13)
    for v in (.5, 1, 10, 100): f.text(xl(v), Y0 + H + 20, kh(v), 12, "#546e7a", "middle")
    f.text(X0 + W / 2, Y0 + H + 45, "ទំហំក្រឡា (ម · log)", 14, INK, "middle"); f.text(X0 - 55, Y0 + H / 2, "ទទឹង (គម)", 14, INK, "middle")
    entry(5, f.save("r05-tradeoff"), "គ្មានផ្កាយរណបណាល្អគ្រប់យ៉ាង",
          ["ក្រឡាតូច តែងមានទទឹងតូច និងតម្លៃខ្ពស់។", "ទទឹងធំ តែងមានក្រឡាធំ ប៉ុន្តែមកម្ដងទៀតញឹកញាប់។", "Sentinel-2 និង Landsat ជាចំណុចសមតុល្យល្អ សម្រាប់ការងារថ្នាក់ខេត្ត និងឥតគិតថ្លៃ។"], .85)
    # 5 same scene 10/30/60 m (Sentinel-2 SHV)
    s = R.shv(2021); im = R.rgb(s[3], s[2], s[1])
    f = Fig(1000, 440).title("Sentinel-2 ១០ ម ធៀបនឹងក្រឡា ៣០ និង ៦០ ម", "ក្រុងព្រះសីហនុ ២០២១ · ពណ៌ពិត")
    c = im.crop((150, 150, 330, 330))
    for i, k in enumerate([1, 3, 6]):
        f.img(c.resize((180 // k, 180 // k), Image.BOX).resize((300, 300), Image.NEAREST), 30 + i * 320, 85, 300, 300); f.text(180 + i * 320, 410, f"{kh(10*k)} ម", 18, IND, "middle", "bold")
    f.source("Copernicus Sentinel-2 (ESA) · កែសម្រួល")
    entry(5, f.save("r05-s2-resolutions"), "លម្អិតដែលបាត់នៅក្រឡាធំ",
          ["១០ ម៖ ឃើញផ្លូវ និងអគារធំៗនៅក្រុងព្រះសីហនុ។", "៣០ ម៖ ឃើញតែតំបន់សំណង់ និងព្រំនៃការឈូសឆាយ។", "៦០ ម៖ ត្រឹមតែលំនាំទូទៅប៉ុណ្ណោះ។"], .15)
